"""Exact inference over the set F of all minimum-fault explanations.

Compilation
-----------
Each snapshot contributes an integer program over its demand vector: a link
load is the integer linear form ``Z = coeffs . q`` scaled by the least common
denominator of the edge's rational route contributions, so capacities and
observation intervals are plain integer constraints.  Trusted observations
are hard constraints of that program.

The incident couples snapshots through one free boolean ``f_d`` per observed
domain (``f_d`` = "domain d is blamed") with the single implication

    not f_d  ->  every observation of d is satisfied,

together with the fault budget ``#blamed <= max_faults``.  Writing k for the
least attainable fault count, the set F of optimal explanations is exactly the
projection of ``base AND #blamed <= k`` onto the demand variables, and the
*optimal blame patterns* (the distinct fault sets realized by explanations in
F) are enumerated from that one program.

Each snapshot's part of F is the union, over optimal blame patterns D, of

    Sol_s(domains \\ D)

where ``Sol_s(R)`` is the snapshot program with all observations of the
domains in R additionally required.  (A requirement set that is infeasible for
that very snapshot contributes an empty set, so the all-snapshot patterns are
enough.)  Those per-snapshot programs hold no fault booleans at all, which
keeps the many interval queries cheap.  If the optimal blame patterns are too
numerous to enumerate, inference falls back to the single all-snapshot
program, which is slower but equally exact.

Solvers are rebuilt per query on purpose: z3 slows down badly when one Solver
object answers many unrelated bound queries in a row.
"""

import time

import z3
from fractions import Fraction

# Decompose only when the optimal blame patterns are few enough to enumerate.
PATTERN_CAP = 24

# A cached solver answers at most this many checks before it is rebuilt, and a
# check slower than this on a used solver is retried on a fresh one: z3 slows
# down dramatically when one Solver object answers many unrelated bounds.
_REFRESH = 8
_SLOW_CHECK = 0.1


class Infeasible(Exception):
    """No feasible explanation exists for the incident."""


def _lin(terms, ctx):
    """Integer linear expression built from coefficient*variable terms."""
    if not terms:
        return z3.IntVal(0, ctx=ctx)
    if len(terms) == 1:
        return terms[0]
    return z3.Sum(terms)


def _rat(value):
    """Exact reduced 'numerator/denominator' string of a Fraction."""
    return '%d/%d' % (value.numerator, value.denominator)


class _Program(object):
    """A fixed constraint set in one z3 context with cached solvers.

    Answering many bound queries with one Solver object that pushes and pops
    makes z3 dramatically slower, so the cached solver is rebuilt from scratch
    every ``refresh`` checks.
    """

    def __init__(self, ctx):
        self.ctx = ctx
        self.cons = []
        self._ids = set()
        self._sol = None
        self._age = 0

    def add(self, cons):
        for con in cons:
            if z3.is_false(con):
                raise Infeasible()
            if z3.is_true(con):
                continue
            key = con.get_id()
            if key in self._ids:
                continue
            self._ids.add(key)
            self.cons.append(con)
        self._sol = None
        self._age = 0

    def _fresh(self):
        self._sol = z3.Solver(ctx=self.ctx)
        if self.cons:
            self._sol.add(self.cons)
        self._age = 0
        return self._sol

    def _check(self, sol, extra):
        sol.push()
        if extra:
            sol.add(extra)
        res = sol.check()
        model = sol.model() if res == z3.sat else None
        sol.pop()
        if res == z3.unknown:
            raise RuntimeError('z3 returned unknown')
        return model

    def model(self, extra=()):
        """Model of the constraints plus extras, or None if unsatisfiable."""
        sol = self._sol
        if sol is None or self._age >= _REFRESH:
            sol = self._fresh()
        age = self._age
        start = time.process_time()
        model = self._check(sol, extra)
        if time.process_time() - start > _SLOW_CHECK and age:
            # Pathologically slow on a used solver: rebuild it and retry.
            sol = self._fresh()
            model = self._check(sol, extra)
        self._age = age + 1
        return model

    def sat(self, extra=()):
        return self.model(extra) is not None

    def _optimize(self, expr, maximize):
        """Optimal value of expr over the constraints, or None if unsat.

        A fresh Optimize object per query keeps z3's branch and bound (which
        is far better at these bounds than a hand-written binary search) from
        ever reusing a warmed-up solver.
        """
        opt = z3.Optimize(ctx=self.ctx)
        if self.cons:
            opt.add(self.cons)
        if maximize:
            opt.maximize(expr)
        else:
            opt.minimize(expr)
        res = opt.check()
        if res == z3.unknown:
            raise RuntimeError('z3 returned unknown')
        if res != z3.sat:
            return None
        return opt.model().eval(expr, model_completion=True).as_long()

    def minimize(self, expr, low, cur):
        """Least value of expr; ``low`` bounds it from below, ``cur`` attains."""
        if cur <= low:
            return cur
        return self._optimize(expr, False)

    def maximize(self, expr, high, cur):
        """Greatest value of expr; ``high`` bounds it, ``cur`` attains."""
        if cur >= high:
            return cur
        return self._optimize(expr, True)


def _ceil_div(num, den):
    return -((-num) // den)


def _propagate(rows, lo, hi, rounds=12):
    """Tighten variable bounds by interval propagation over the rows.

    ``rows`` holds ``(coeffs, low, high)`` with nonnegative integer
    coefficients and integer bounds (None means unbounded).  The returned
    bounds are valid for every integer point satisfying all rows.
    """
    count = len(lo)
    for _ in range(rounds):
        changed = False
        for coeffs, rlo, rhi in rows:
            for c in range(count):
                a = coeffs[c]
                if not a:
                    continue
                rest_lo = 0
                rest_hi = 0
                for c2 in range(count):
                    if c2 != c and coeffs[c2]:
                        rest_lo += coeffs[c2] * lo[c2]
                        rest_hi += coeffs[c2] * hi[c2]
                if rlo is not None:
                    bound = _ceil_div(rlo - rest_hi, a)
                    if bound > lo[c]:
                        lo[c] = bound
                        changed = True
                if rhi is not None:
                    bound = (rhi - rest_lo) // a
                    if bound < hi[c]:
                        hi[c] = bound
                        changed = True
                if lo[c] > hi[c]:
                    return lo, hi
        if not changed:
            break
    return lo, hi


class _Snapshot(object):
    """Variables and integer constraints describing one snapshot.

    ``base`` holds the demand box, the capacity limits and the trusted
    observations; ``dom_obs`` maps a domain to the satisfaction formulas of
    its observations, which a caller may add as requirements.
    """

    def __init__(self, inst, si, ctx, prefix):
        self.inst = inst
        self.si = si
        self.C = len(inst.commodities)
        self.E = len(inst.edges)
        self.q = [z3.Int('%sq!%d!%d' % (prefix, si, c), ctx=ctx)
                  for c in range(self.C)]
        self.link = []
        self.ingress = {}
        self.egress = {}
        cons = []
        bounds = inst.snapshots[si].bounds
        for c in range(self.C):
            cons.append(self.q[c] >= bounds[c][0])
            cons.append(self.q[c] <= bounds[c][1])
        for ei in range(self.E):
            scale, coeffs = inst.edge_coeff[ei]
            terms = [coeffs[c] * self.q[c] for c in range(self.C) if coeffs[c]]
            expr = _lin(terms, ctx)
            self.link.append(expr)
            if terms:
                cons.append(expr <= scale * inst.edges[ei].capacity)
        for node in inst.nodes:
            iidx = inst.ingress_indices[node]
            if iidx:
                self.ingress[node] = _lin([self.q[c] for c in iidx], ctx)
            eidx = inst.egress_indices[node]
            if eidx:
                self.egress[node] = _lin([self.q[c] for c in eidx], ctx)
        self.dom_obs = {}
        self.obs_specs = []   # (domain or None, satisfied, violated)
        for obs in inst.snapshots[si].observations:
            if obs.metric == 'demand':
                expr = self.q[inst.commodity_index[obs.target]]
                lo, hi = obs.lower, obs.upper
            elif obs.metric == 'link':
                ei = inst.edge_index[obs.target]
                scale = inst.edge_coeff[ei][0]
                expr = self.link[ei]
                lo, hi = scale * obs.lower, scale * obs.upper
            elif obs.metric == 'ingress':
                expr = self.ingress.get(obs.target, z3.IntVal(0, ctx=ctx))
                lo, hi = obs.lower, obs.upper
            else:
                expr = self.egress.get(obs.target, z3.IntVal(0, ctx=ctx))
                lo, hi = obs.lower, obs.upper
            satisfied = z3.And(expr >= lo, expr <= hi)
            violated = z3.Or(expr < lo, expr > hi)
            self.obs_specs.append((obs.domain, satisfied, violated))
            if obs.domain is None:
                cons.append(satisfied)
            else:
                self.dom_obs.setdefault(obs.domain, []).append(satisfied)
        self.base = cons


class _Engine(object):
    """Answers every query about the set F of optimal explanations."""

    def __init__(self, inst):
        self.inst = inst
        self.S = len(inst.snapshots)
        self.C = len(inst.commodities)
        self.E = len(inst.edges)
        self.ctx = z3.Context()
        self.snaps = [_Snapshot(inst, si, self.ctx, '') for si in range(self.S)]
        self.fault_domains = inst.observed_domains()
        self.f = {}
        for domain in self.fault_domains:
            self.f[domain] = z3.Bool('f!%d' % inst.domain_index[domain], ctx=self.ctx)
        self.fvars = [self.f[d] for d in self.fault_domains]
        cons = []
        for snap in self.snaps:
            cons.extend(snap.base)
            for domain, sats in snap.dom_obs.items():
                blame = self.f[domain]
                for sat in sats:
                    cons.append(z3.Or(blame, sat))
        self.prog = _Program(self.ctx)
        self.prog.add(cons)
        self.k = None
        self.domain_violated = {}
        self.domain_satisfied = {}
        for domain in self.fault_domains:
            viols = []
            sats = []
            for snap in self.snaps:
                for dom, sat, viol in snap.obs_specs:
                    if dom == domain:
                        viols.append(viol)
                        sats.append(sat)
            self.domain_violated[domain] = viols[0] if len(viols) == 1 else z3.Or(viols)
            self.domain_satisfied[domain] = sats[0] if len(sats) == 1 else z3.And(sats)

    # ------------------------------------------------------------- helpers

    def _budget(self, count):
        if not self.fvars or count >= len(self.fvars):
            return z3.BoolVal(True, ctx=self.ctx)
        return z3.PbLe([(f, 1) for f in self.fvars], count)

    def _actual_faults(self, demands, loads):
        """Actual faulty-domain set of one explanation (exact recheck)."""
        inst = self.inst
        faulty = set()
        for i, snap in enumerate(inst.snapshots):
            for obs in snap.observations:
                if not (obs.lower <= inst.true_value(obs, demands[i], loads[i])
                        <= obs.upper):
                    faulty.add(obs.domain)
        return faulty

    def _witness(self, demands, loads, faulty):
        return {
            'demands': [[v for v in row] for row in demands],
            'links': [[_rat(v) for v in row] for row in loads],
            'faults': sorted(faulty),
        }

    def _agreement(self, snap, local):
        """(all-agree, some-disagree) constraints for one snapshot program."""
        agree = []
        disagree = []
        snap_data = self.inst.snapshots[snap.si]
        for ci in range(snap.C):
            c = snap_data.controller[ci]
            t = snap_data.tolerance
            agree.append(local.q[ci] >= c - t)
            agree.append(local.q[ci] <= c + t)
            disagree.append(z3.Or(local.q[ci] < c - t, local.q[ci] > c + t))
        return agree, disagree

    # ----------------------------------------------------------------- run

    def run(self):
        inst = self.inst
        # Implied demand bounds from each snapshot's own hard constraints
        # (box, capacities, trusted observations) speed up every later query.
        for si in range(self.S):
            rows, _unused = self._scope_rows(si, frozenset())
            lo = [b[0] for b in inst.snapshots[si].bounds]
            hi = [b[1] for b in inst.snapshots[si].bounds]
            lo, hi = _propagate(rows, lo, hi)
            extra = []
            for ci in range(self.C):
                if lo[ci] > inst.snapshots[si].bounds[ci][0]:
                    extra.append(self.snaps[si].q[ci] >= lo[ci])
                if hi[ci] < inst.snapshots[si].bounds[ci][1]:
                    extra.append(self.snaps[si].q[ci] <= hi[ci])
            if extra:
                self.prog.add(extra)
        if not self.prog.sat([self._budget(inst.max_faults)]):
            raise Infeasible()
        lo, hi = 0, inst.max_faults
        while lo < hi:
            mid = (lo + hi) // 2
            if self.prog.sat([self._budget(mid)]):
                hi = mid
            else:
                lo = mid + 1
        self.k = lo
        self.prog.add([self._budget(self.k)])
        patterns = self._patterns()
        if patterns is not None:
            body = self._decomposed(patterns)
            if body is not None:
                return body
        return self._full()

    def _patterns(self):
        """All optimal blame patterns, or None when there are too many.

        Under the budget ``#blamed <= k`` every model blames exactly its
        actual fault set, so solving and blocking repeatedly enumerates the
        fault sets realized by F.
        """
        if not self.fvars:
            return [frozenset()]
        blocking = []
        found = []
        while len(found) <= PATTERN_CAP:
            model = self.prog.model(blocking)
            if model is None:
                return found
            blamed = frozenset(d for d in self.fault_domains
                               if model.eval(self.f[d], model_completion=True))
            found.append(blamed)
            lits = [self.f[d] if d in blamed else z3.Not(self.f[d])
                    for d in self.fault_domains]
            blocking.append(z3.Not(z3.And(lits)))
        return None

    # -------------------------------------------------------- decomposition

    def _scope_rows(self, si, required):
        """Integer rows of one snapshot scope, for interval propagation.

        Returns ``(rows, bounds_by_coeffs)`` where every row is
        ``(coefficients, low, high)`` over the snapshot's demand vector and
        ``bounds_by_coeffs`` aggregates the rows sharing a coefficient vector
        (capacity limits and required observations included).
        """
        inst = self.inst
        C = self.C
        rows = []
        bounds = {}

        def add_row(coeffs, rlo, rhi):
            key = tuple(coeffs)
            current = bounds.get(key)
            if current is None:
                bounds[key] = [rlo, rhi]
            else:
                if rlo is not None and (current[0] is None or rlo > current[0]):
                    current[0] = rlo
                if rhi is not None and (current[1] is None or rhi < current[1]):
                    current[1] = rhi
            rows.append((list(coeffs), rlo, rhi))

        for ei in range(self.E):
            scale, coeffs = inst.edge_coeff[ei]
            if any(coeffs):
                add_row(coeffs, None, scale * inst.edges[ei].capacity)
        for obs in inst.snapshots[si].observations:
            if obs.domain is not None and obs.domain not in required:
                continue
            if obs.metric == 'demand':
                coeffs = [0] * C
                coeffs[inst.commodity_index[obs.target]] = 1
                rlo, rhi = obs.lower, obs.upper
            elif obs.metric == 'link':
                ei = inst.edge_index[obs.target]
                scale, coeffs = inst.edge_coeff[ei]
                if not any(coeffs):
                    continue
                rlo, rhi = scale * obs.lower, scale * obs.upper
            elif obs.metric == 'ingress':
                coeffs = [0] * C
                for ci in inst.ingress_indices[obs.target]:
                    coeffs[ci] = 1
                rlo, rhi = obs.lower, obs.upper
            else:
                coeffs = [0] * C
                for ci in inst.egress_indices[obs.target]:
                    coeffs[ci] = 1
                rlo, rhi = obs.lower, obs.upper
            add_row(coeffs, rlo, rhi)
        return rows, bounds

    def _decomposed(self, patterns):
        """Inference over per-snapshot programs; None triggers the fallback."""
        inst = self.inst
        S, C, E = self.S, self.C, self.E
        k = self.k
        all_domains = frozenset(self.fault_domains)
        requirements = [all_domains - pattern for pattern in patterns]

        # One program per distinct requirement scope of each snapshot.
        ctx = z3.Context()
        scope_snapshot = []     # snapshot index of each scope
        scope_local = []        # snapshot program of each scope
        scope_prog = []         # program (base + requirements) of each scope
        scope_models = []       # a model of each scope
        scope_bounds = []       # propagated demand bounds of each scope
        scope_row_bounds = []   # aggregated row bounds by coefficient vector
        scope_of = []           # pattern -> snapshot -> scope index
        keys = {}
        for req in requirements:
            per_snap = []
            for si in range(S):
                sig = tuple(sorted(d for d in req
                                   if self.snaps[si].dom_obs.get(d)))
                index = keys.get((si, sig))
                if index is None:
                    local = _Snapshot(inst, si, ctx, 's')
                    formulas = []
                    for d in req:
                        formulas.extend(local.dom_obs.get(d, ()))
                    prog = _Program(ctx)
                    prog.add(local.base)
                    if formulas:
                        prog.add(formulas)
                    # Propagated bounds are implied by the scope's own
                    # constraints; asserting them helps z3 enormously.
                    rows, row_bounds = self._scope_rows(si, req)
                    box = inst.snapshots[si].bounds
                    lo = [b[0] for b in box]
                    hi = [b[1] for b in box]
                    lo, hi = _propagate(rows, lo, hi)
                    for ci in range(C):
                        if lo[ci] > box[ci][0]:
                            prog.add([local.q[ci] >= lo[ci]])
                        if hi[ci] < box[ci][1]:
                            prog.add([local.q[ci] <= hi[ci]])
                    model = prog.model()
                    if model is None:
                        return None
                    index = len(scope_snapshot)
                    keys[(si, sig)] = index
                    scope_snapshot.append(si)
                    scope_local.append(local)
                    scope_prog.append(prog)
                    scope_models.append(model)
                    scope_bounds.append((lo, hi))
                    scope_row_bounds.append(row_bounds)
                per_snap.append(index)
            scope_of.append(per_snap)

        def scope_indices(si):
            return [j for j in range(len(scope_snapshot))
                    if scope_snapshot[j] == si]

        def scope_demands(index):
            return [scope_models[index].eval(v, model_completion=True).as_long()
                    for v in scope_local[index].q]

        # Demand ranges over the union of scopes.
        dmin = [[None] * C for _ in range(S)]
        dmax = [[None] * C for _ in range(S)]
        dmin_at = [[None] * C for _ in range(S)]
        dmax_at = [[None] * C for _ in range(S)]
        for si in range(S):
            indices = scope_indices(si)
            values = {j: scope_demands(j) for j in indices}
            lows = {j: scope_bounds[j][0] for j in indices}
            highs = {j: scope_bounds[j][1] for j in indices}
            for ci in range(C):
                low_all = min(lows[j][ci] for j in indices)
                high_all = max(highs[j][ci] for j in indices)
                best_min = min(values[j][ci] for j in indices)
                best_max = max(values[j][ci] for j in indices)
                argmin = min(indices, key=lambda j: values[j][ci])
                argmax = max(indices, key=lambda j: values[j][ci])
                if best_min > low_all:
                    for j in indices:
                        if values[j][ci] == lows[j][ci]:
                            continue
                        value = scope_prog[j].minimize(scope_local[j].q[ci],
                                                       lows[j][ci], values[j][ci])
                        if value is None:
                            return None
                        if value < best_min:
                            best_min = value
                            argmin = j
                        if best_min == low_all:
                            break
                if best_max < high_all:
                    for j in indices:
                        if values[j][ci] == highs[j][ci]:
                            continue
                        value = scope_prog[j].maximize(scope_local[j].q[ci],
                                                       highs[j][ci], values[j][ci])
                        if value is None:
                            return None
                        if value > best_max:
                            best_max = value
                            argmax = j
                        if best_max == high_all:
                            break
                dmin[si][ci] = best_min
                dmax[si][ci] = best_max
                dmin_at[si][ci] = argmin
                dmax_at[si][ci] = argmax

        # Link load ranges over the union of scopes.
        lmin = [[None] * E for _ in range(S)]
        lmax = [[None] * E for _ in range(S)]
        for si in range(S):
            for j in scope_indices(si):
                local = scope_local[j]
                prog = scope_prog[j]
                demands = scope_demands(j)
                low_demands, high_demands = scope_bounds[j]
                cache = {}
                for ei in range(E):
                    scale, coeffs = inst.edge_coeff[ei]
                    if not any(coeffs):
                        mn = mx = 0
                    else:
                        sig = (scale, tuple(coeffs),
                               scale * inst.edges[ei].capacity)
                        if sig in cache:
                            mn, mx = cache[sig]
                        else:
                            row = scope_row_bounds[j].get(tuple(coeffs),
                                                         [None, None])
                            zlb = 0
                            zub = scale * inst.edges[ei].capacity
                            if row[1] is not None and row[1] < zub:
                                zub = row[1]
                            for ci in range(C):
                                if coeffs[ci]:
                                    zlb += coeffs[ci] * low_demands[ci]
                                    zub += coeffs[ci] * high_demands[ci]
                            if row[0] is not None and row[0] > zlb:
                                zlb = row[0]
                            if zlb > zub:
                                zlb = zub
                            cur = 0
                            for ci in range(C):
                                if coeffs[ci]:
                                    cur += coeffs[ci] * demands[ci]
                            if zlb == zub:
                                mn = mx = zlb
                            elif cur == zlb:
                                mn = cur
                                mx = prog.maximize(local.link[ei], zub, cur)
                                if mx is None:
                                    return None
                            elif cur == zub:
                                mn = prog.minimize(local.link[ei], zlb, cur)
                                mx = cur
                                if mn is None:
                                    return None
                            else:
                                mn = prog.minimize(local.link[ei], zlb, cur)
                                mx = prog.maximize(local.link[ei], zub, cur)
                                if mn is None or mx is None:
                                    return None
                            cache[sig] = (mn, mx)
                    if lmin[si][ei] is None or mn < lmin[si][ei]:
                        lmin[si][ei] = mn
                    if lmax[si][ei] is None or mx > lmax[si][ei]:
                        lmax[si][ei] = mx

        # Controller verdicts.
        verdicts = []
        for si in range(S):
            some_agree = False
            some_disagree = False
            for j in scope_indices(si):
                local = scope_local[j]
                prog = scope_prog[j]
                agree, disagree = self._agreement(local, local)
                if C == 0:
                    some_agree = True
                elif not some_agree and prog.sat(agree):
                    some_agree = True
                if C > 0 and not some_disagree:
                    if prog.sat([z3.Or(disagree)]):
                        some_disagree = True
            if some_agree:
                verdicts.append('consistent' if not some_disagree
                                else 'undetermined')
            else:
                verdicts.append('inconsistent')

        # Witness from the first pattern.
        witness_demands = []
        witness_loads = []
        for si in range(S):
            witness_demands.append(scope_demands(scope_of[0][si]))
            witness_loads.append(inst.edge_loads(witness_demands[-1]))
        faulty = self._actual_faults(witness_demands, witness_loads)
        if faulty != patterns[0] or len(faulty) != k:
            return None
        witness = self._witness(witness_demands, witness_loads, faulty)

        unique = all(dmin[i][ci] == dmax[i][ci]
                    for i in range(S) for ci in range(C))

        # A second explanation whose demand matrix differs, when ambiguous.
        alternative = None
        if not unique:
            for i in range(S):
                for ci in range(C):
                    if dmin[i][ci] == dmax[i][ci]:
                        continue
                    if witness_demands[i][ci] != dmin[i][ci]:
                        target, scope = dmin[i][ci], dmin_at[i][ci]
                    else:
                        target, scope = dmax[i][ci], dmax_at[i][ci]
                    chosen = None
                    for pi in range(len(patterns)):
                        if scope_of[pi][i] == scope:
                            chosen = pi
                            break
                    if chosen is None:
                        return None
                    model = scope_prog[scope].model(
                        [scope_local[scope].q[ci] == target])
                    if model is None:
                        return None
                    alt_demands = [None] * S
                    alt_demands[i] = [model.eval(v, model_completion=True).as_long()
                                      for v in scope_local[scope].q]
                    for j in range(S):
                        if j != i:
                            alt_demands[j] = scope_demands(scope_of[chosen][j])
                    alt_loads = [inst.edge_loads(row) for row in alt_demands]
                    alt_faults = self._actual_faults(alt_demands, alt_loads)
                    if alt_faults != patterns[chosen] or len(alt_faults) != k:
                        return None
                    if alt_demands == witness_demands:
                        return None
                    alternative = self._witness(alt_demands, alt_loads, alt_faults)
                    break
                if alternative is not None:
                    break

        forced = set(patterns[0])
        possible = set(patterns[0])
        for pattern in patterns[1:]:
            forced &= pattern
            possible |= pattern

        snapshots = []
        for i in range(S):
            scale_of = [inst.edge_coeff[ei][0] for ei in range(E)]
            snapshots.append({
                'id': inst.snapshots[i].id,
                'demands': [[dmin[i][ci], dmax[i][ci]] for ci in range(C)],
                'links': [[_rat(Fraction(lmin[i][ei], scale_of[ei])),
                           _rat(Fraction(lmax[i][ei], scale_of[ei]))]
                          for ei in range(E)],
                'verdict': verdicts[i],
            })
        return {
            'status': 'unique' if unique else 'ambiguous',
            'min_faults': k,
            'faults': {'forced': sorted(forced), 'possible': sorted(possible)},
            'snapshots': snapshots,
            'witness': witness,
            'alternative': alternative,
        }

    # ---------------------------------------------------------- full program

    def _full(self):
        """Inference from the single all-snapshot program (always exact)."""
        inst = self.inst
        S, C, E = self.S, self.C, self.E
        prog = self.prog

        model = prog.model()
        demands = [[model.eval(var, model_completion=True).as_long()
                    for var in snap.q] for snap in self.snaps]
        loads = [inst.edge_loads(demands[i]) for i in range(S)]
        faulty = self._actual_faults(demands, loads)
        if len(faulty) != self.k:
            raise RuntimeError('witness fault count mismatch')
        witness = self._witness(demands, loads, faulty)

        dmin = [[None] * C for _ in range(S)]
        dmax = [[None] * C for _ in range(S)]
        for i in range(S):
            bounds = inst.snapshots[i].bounds
            for ci in range(C):
                lo, hi = bounds[ci]
                cur = demands[i][ci]
                dmin[i][ci] = prog.minimize(self.snaps[i].q[ci], lo, cur)
                dmax[i][ci] = prog.maximize(self.snaps[i].q[ci], hi, cur)
                if dmin[i][ci] is None or dmax[i][ci] is None:
                    raise RuntimeError('feasible program became unsatisfiable')

        lmin = [[None] * E for _ in range(S)]
        lmax = [[None] * E for _ in range(S)]
        for i in range(S):
            bounds = inst.snapshots[i].bounds
            los = [b[0] for b in bounds]
            his = [b[1] for b in bounds]
            snap = self.snaps[i]
            cache = {}
            for ei in range(E):
                scale, coeffs = inst.edge_coeff[ei]
                if not any(coeffs):
                    lmin[i][ei] = lmax[i][ei] = 0
                    continue
                sig = (scale, tuple(coeffs), scale * inst.edges[ei].capacity)
                if sig in cache:
                    mn, mx = cache[sig]
                else:
                    zlb = 0
                    zub = scale * inst.edges[ei].capacity
                    for ci in range(C):
                        if coeffs[ci]:
                            zlb += coeffs[ci] * los[ci]
                            zub += coeffs[ci] * his[ci]
                    if zlb > zub:
                        zlb = zub
                    cur = 0
                    for ci in range(C):
                        if coeffs[ci]:
                            cur += coeffs[ci] * demands[i][ci]
                    if zlb == zub:
                        mn = mx = zlb
                    else:
                        mn = prog.minimize(snap.link[ei], zlb, cur)
                        mx = prog.maximize(snap.link[ei], zub, cur)
                        if mn is None or mx is None:
                            raise RuntimeError('feasible program became unsatisfiable')
                    cache[sig] = (mn, mx)
                lmin[i][ei] = mn
                lmax[i][ei] = mx

        forced = []
        possible = []
        for domain in self.fault_domains:
            if prog.sat([self.domain_violated[domain]]):
                possible.append(domain)
                if not prog.sat([self.domain_satisfied[domain]]):
                    forced.append(domain)

        verdicts = []
        for i in range(S):
            snap = self.snaps[i]
            agree, disagree = self._agreement(snap, snap)
            some_agree = C == 0 or prog.sat(agree)
            some_disagree = C > 0 and prog.sat([z3.Or(disagree)])
            if some_agree:
                verdicts.append('consistent' if not some_disagree
                                else 'undetermined')
            else:
                verdicts.append('inconsistent')

        unique = all(dmin[i][ci] == dmax[i][ci]
                     for i in range(S) for ci in range(C))

        alternative = None
        if not unique:
            for i in range(S):
                for ci in range(C):
                    if dmin[i][ci] == dmax[i][ci]:
                        continue
                    target = dmin[i][ci] if demands[i][ci] != dmin[i][ci] \
                        else dmax[i][ci]
                    model = prog.model([self.snaps[i].q[ci] == target])
                    if model is None:
                        raise RuntimeError('range endpoint not attained')
                    alt_demands = [[model.eval(var, model_completion=True).as_long()
                                    for var in snap.q] for snap in self.snaps]
                    alt_loads = [inst.edge_loads(row) for row in alt_demands]
                    alt_faults = self._actual_faults(alt_demands, alt_loads)
                    if len(alt_faults) != self.k:
                        raise RuntimeError('alternative fault count mismatch')
                    alternative = self._witness(alt_demands, alt_loads, alt_faults)
                    break
                if alternative is not None:
                    break

        snapshots = []
        for i in range(S):
            scale_of = [inst.edge_coeff[ei][0] for ei in range(E)]
            snapshots.append({
                'id': inst.snapshots[i].id,
                'demands': [[dmin[i][ci], dmax[i][ci]] for ci in range(C)],
                'links': [[_rat(Fraction(lmin[i][ei], scale_of[ei])),
                           _rat(Fraction(lmax[i][ei], scale_of[ei]))]
                          for ei in range(E)],
                'verdict': verdicts[i],
            })
        return {
            'status': 'unique' if unique else 'ambiguous',
            'min_faults': self.k,
            'faults': {'forced': sorted(forced), 'possible': sorted(possible)},
            'snapshots': snapshots,
            'witness': witness,
            'alternative': alternative,
        }


def analyze(inst):
    """Full analysis of a validated instance; returns the response body."""
    engine = _Engine(inst)
    try:
        return engine.run()
    finally:
        engine.ctx = None
        engine.prog = None
        engine.snaps = None
